WITH base AS (SELECT *, FLOOR(monthly_fee) AS monthly_fee_whole FROM subscriptions WHERE monthly_fee < 130), subscriptions_stats AS (SELECT status, YEAR(start_date) AS start_year, MIN(monthly_fee) AS min_monthly_fee, ROUND(STDDEV(monthly_fee_whole), 2) AS stddev_monthly_fee_whole FROM base GROUP BY status, YEAR(start_date)) SELECT * FROM subscriptions_stats ORDER BY status, start_year LIMIT 3;
